//! Anchor camouflage and anchor draw (L07-J; G17).
//!
//! `fixtures/object-scene-producer-brush-anchor/oracle.txt` was generated by
//! `tools/gen_anchor_oracle.js` from baseline fbe4b8a3: the verbatim
//! `applyBitmapBrushTexture` and `regenerate` (bitmap-brush.js) and `colorHex8` (app.js) run
//! in a Node vm with real Paper.js 0.12.18 colors. Row format:
//! `A id fill stroke opacity preS preO | stroke opacity preS preO (after apply) | stroke
//! opacity preS preO (after regenerate)`; `~` is `undefined`, opacities are IEEE hex.

use super::{
    anchor_draw, camouflage, AnchorDraw, AnchorError, AnchorRules, AnchorState, Remembered,
};
use crate::evaluation::object_scene_style_kernels::object_scene_style_paint::SceneSolid;
use crate::object_document::SolidFill;
use serde_json::Number;

const ORACLE: &str = include_str!("fixtures/object-scene-producer-brush-anchor/oracle.txt");

struct Row {
    id: String,
    has_fill: bool,
    authored: AnchorState,
    applied: AnchorState,
    regenerated: AnchorState,
}

fn number(token: &str) -> Option<f64> {
    (token != "~").then(|| f64::from_bits(u64::from_str_radix(token, 16).expect("ieee hex")))
}

fn remembered(token: &str) -> Remembered<Option<String>> {
    match token {
        "~" => Remembered::Unset,
        "null" => Remembered::Set(None),
        text => Remembered::Set(Some(text.to_owned())),
    }
}

fn state(stroke: &str, opacity: &str, pre_stroke: &str, pre_opacity: &str) -> AnchorState {
    AnchorState {
        stroke: (stroke != "null" && stroke != "-").then(|| stroke.to_owned()),
        opacity: number(opacity),
        pre_stroke: remembered(pre_stroke),
        pre_opacity: match number(pre_opacity) {
            Some(value) => Remembered::Set(value),
            None => Remembered::Unset,
        },
    }
}

fn rows() -> Vec<Row> {
    ORACLE
        .lines()
        .filter(|line| line.starts_with("A "))
        .map(|line| {
            let cols: Vec<&str> = line.split_whitespace().collect();
            assert_eq!(cols.len(), 17, "{line}");
            assert_eq!((cols[7], cols[12]), ("|", "|"), "{line}");
            Row {
                id: cols[1].to_owned(),
                has_fill: cols[2] != "none",
                authored: state(cols[3], cols[4], cols[5], cols[6]),
                applied: state(cols[8], cols[9], cols[10], cols[11]),
                regenerated: state(cols[13], cols[14], cols[15], cols[16]),
            }
        })
        .collect()
}

/// Equality that tells `-0` from `0` (the derived `PartialEq` of `f64` does not).
fn same(a: &AnchorState, b: &AnchorState) -> bool {
    let bits = |value: Option<f64>| value.map(f64::to_bits);
    let pre = |state: &AnchorState| match state.pre_opacity {
        Remembered::Unset => None,
        Remembered::Set(value) => Some(value.to_bits()),
    };
    a.stroke == b.stroke
        && bits(a.opacity) == bits(b.opacity)
        && a.pre_stroke == b.pre_stroke
        && pre(a) == pre(b)
}

fn mismatches(rules: &AnchorRules) -> Vec<String> {
    rows()
        .iter()
        .filter(|row| {
            let applied = rules.camouflage(row.has_fill, &row.authored);
            let again = rules.camouflage(row.has_fill, &applied);
            !(same(&applied, &row.applied) && same(&again, &row.regenerated))
        })
        .map(|row| row.id.clone())
        .collect()
}

fn fill(r: f64, g: f64, b: f64, a: f64) -> SolidFill {
    let n = |v: f64| Number::from_f64(v).expect("finite");
    SolidFill {
        kind: "solid".to_owned(),
        r: n(r),
        g: n(g),
        b: n(b),
        a: n(a),
    }
}

fn authored(stroke: Option<&str>, opacity: Option<f64>) -> AnchorState {
    AnchorState {
        stroke: stroke.map(str::to_owned),
        opacity,
        pre_stroke: Remembered::Unset,
        pre_opacity: Remembered::Unset,
    }
}

#[test]
fn oracle_header_and_counts_are_pinned() {
    assert_eq!(rows().len(), 468);
    assert!(ORACLE.contains("(baseline fbe4b8a33e6d5a229f014154df2ba21988a9fabc)"));
    for sha in [
        "352668c4a7c2dd750ba393b2da9189bf5aa5fa006c2592b911301a1982102f60",
        "0969193499a144908d036fba2b2a80fd8a4a9cda4dff94905b77e9b82fbb1359",
        "ea3c0613f41b0aab3cd1688ee015b3725536e75ccef6ff54ed70cd4807987894",
        "13526b252be3856db63b096ca282270454a3bb4567943e137875d9ced54ce9ba",
    ] {
        assert!(ORACLE.contains(sha), "{sha}");
    }
    let filled = rows().iter().filter(|row| row.has_fill).count();
    assert_eq!((filled, rows().len() - filled), (312, 156));
}

#[test]
fn camouflage_equals_the_verbatim_baseline_on_every_row_and_is_a_fixed_point() {
    assert_eq!(mismatches(&AnchorRules::BASELINE), Vec::<String>::new());
    for row in rows() {
        let again = camouflage(row.has_fill, &camouflage(row.has_fill, &row.authored));
        assert!(same(&again, &row.regenerated), "row {}", row.id);
        assert!(same(&row.applied, &row.regenerated), "row {}", row.id);
    }
}

#[test]
fn camouflage_literals_follow_the_two_baseline_cases() {
    // A fill keeps painting; only the stroke goes, remembered as the colorHex8 string.
    let filled = camouflage(true, &authored(Some("#336699"), Some(0.5)));
    assert_eq!(filled.stroke, None);
    assert_eq!(filled.opacity, Some(0.5));
    assert_eq!(
        filled.pre_stroke,
        Remembered::Set(Some("#336699".to_owned()))
    );
    assert_eq!(filled.pre_opacity, Remembered::Unset);
    // No authored stroke at all remembers an explicit null.
    let bare = camouflage(true, &authored(None, Some(1.0)));
    assert_eq!(bare.pre_stroke, Remembered::Set(None));
    // No fill: the whole anchor goes invisible, the old opacity is remembered, the stroke stays.
    let hidden = camouflage(false, &authored(Some("#336699"), Some(0.25)));
    assert_eq!(hidden.opacity, Some(0.0));
    assert_eq!(hidden.pre_opacity, Remembered::Set(0.25));
    assert_eq!(hidden.stroke, Some("#336699".to_owned()));
    assert_eq!(hidden.pre_stroke, Remembered::Unset);
    // An undefined opacity is remembered as Paper's default of 1.
    let undefined = camouflage(false, &authored(None, None));
    assert_eq!(undefined.pre_opacity, Remembered::Set(1.0));
    // Only the FIRST application remembers: a later one keeps what is already there.
    let mut remembered_before = authored(Some("#00ff00"), Some(0.9));
    remembered_before.pre_stroke = Remembered::Set(Some("#aabbccdd".to_owned()));
    remembered_before.pre_opacity = Remembered::Set(0.75);
    assert_eq!(
        camouflage(true, &remembered_before).pre_stroke,
        Remembered::Set(Some("#aabbccdd".to_owned()))
    );
    assert_eq!(
        camouflage(false, &remembered_before).pre_opacity,
        Remembered::Set(0.75)
    );
}

fn num(value: f64) -> Number {
    Number::from_f64(value).expect("finite")
}

fn solid(r: f64, g: f64, b: f64, a: f64) -> SceneSolid {
    SceneSolid::from_fill(&fill(r, g, b, a)).expect("representable")
}

#[test]
fn anchor_draw_reads_the_record_and_never_the_remembered_values() {
    // A filled anchor: the record has the fill, NO stroke, opacity 0.5. The authored red
    // stroke is only remembered (pre_stroke), never drawn.
    let stored = camouflage(true, &authored(Some("#ff0000"), Some(0.5)));
    let draw = anchor_draw(
        Some(&fill(0.25, 0.5, 0.75, 1.0)),
        None,
        &num(0.5),
        &stored.restore(),
    )
    .unwrap();
    assert_eq!(
        draw,
        AnchorDraw {
            fill: Some(solid(0.25, 0.5, 0.75, 1.0)),
            stroke: None,
            opacity: 0.5
        }
    );
    assert_eq!(
        stored.pre_stroke,
        Remembered::Set(Some("#ff0000".to_owned()))
    );
    // The opacity is the record's, not the state's: the drawn value follows the record.
    let draw = anchor_draw(
        Some(&fill(0.25, 0.5, 0.75, 1.0)),
        None,
        &num(0.25),
        &stored.restore(),
    )
    .unwrap();
    assert_eq!(draw.opacity, 0.25);
    // An unfilled anchor: no fill, the kept authored stroke, opacity 0; the old opacity 0.8
    // is remembered, never drawn.
    let invisible = camouflage(false, &authored(Some("#336699"), Some(0.8)));
    let kept = fill(0.2, 0.4, 0.6, 1.0);
    let draw = anchor_draw(None, Some(&kept), &num(0.0), &invisible.restore()).unwrap();
    assert_eq!(
        draw,
        AnchorDraw {
            fill: None,
            stroke: Some(solid(0.2, 0.4, 0.6, 1.0)),
            opacity: 0.0
        }
    );
    assert_eq!(invisible.pre_opacity, Remembered::Set(0.8));
}

#[test]
fn an_anchor_that_cannot_be_drawn_is_a_typed_error() {
    let filled = camouflage(true, &authored(None, Some(1.0))).restore();
    // A fill or a stroke outside 0..1 is not a straight RGBA.
    assert!(matches!(
        anchor_draw(Some(&fill(2.0, 0.0, 0.0, 1.0)), None, &num(1.0), &filled),
        Err(AnchorError::Fill(_))
    ));
    let unfilled = camouflage(false, &authored(None, Some(1.0))).restore();
    assert!(matches!(
        anchor_draw(None, Some(&fill(0.0, -1.0, 0.0, 1.0)), &num(0.0), &unfilled),
        Err(AnchorError::Fill(_))
    ));
}

#[test]
fn a_record_that_contradicts_the_remembered_camouflage_is_a_typed_error() {
    let red = fill(1.0, 0.0, 0.0, 1.0);
    let filled = camouflage(true, &authored(Some("#ff0000"), Some(1.0))).restore();
    let unfilled = camouflage(false, &authored(Some("#ff0000"), Some(1.0))).restore();
    let never = authored(Some("#ff0000"), Some(1.0)).restore();
    let cases = [
        // A filled record that still has a stroke was not camouflaged.
        (
            Some(&red),
            Some(&red),
            1.0,
            &filled,
            "filled-anchor-keeps-a-stroke",
        ),
        // A filled record whose stroke was never remembered (visible or not).
        (
            Some(&red),
            None,
            1.0,
            &never,
            "filled-anchor-without-remembered-stroke",
        ),
        (
            Some(&red),
            None,
            0.0,
            &never,
            "filled-anchor-without-remembered-stroke",
        ),
        // An unfilled record with a visible opacity was not camouflaged.
        (
            None,
            Some(&red),
            0.5,
            &unfilled,
            "unfilled-anchor-is-visible",
        ),
        // An unfilled invisible record whose opacity was never remembered.
        (
            None,
            Some(&red),
            0.0,
            &never,
            "unfilled-anchor-without-remembered-opacity",
        ),
    ];
    for (record_fill, stroke, opacity, restore, why) in cases {
        assert_eq!(
            anchor_draw(record_fill, stroke, &num(opacity), restore),
            Err(AnchorError::CamouflageDisagrees(why)),
            "{why}"
        );
    }
    // The two consistent shapes pass (the controls above differ from them in one member).
    assert!(anchor_draw(Some(&red), None, &num(1.0), &filled).is_ok());
    assert!(anchor_draw(None, Some(&red), &num(0.0), &unfilled).is_ok());
}

#[test]
fn mutating_remember_first_only_is_caught_by_the_baseline_rows() {
    let rules = AnchorRules {
        remember_first_only: false,
        ..AnchorRules::BASELINE
    };
    let bad = mismatches(&rules);
    // `mismatches` checks the first application AND the re-application: 273 rows differ on
    // the first application alone, 349 on the re-application alone, 400 on either.
    assert_eq!(bad.len(), 400);
    // Row 2: the memory is already set, the mutant overwrites it.
    assert!(bad.contains(&"2".to_owned()));
    // Row 1 survives the first application but the re-application remembers the already
    // camouflaged opacity (0) instead of the authored one (1), so the mutant is caught there.
    assert!(bad.contains(&"1".to_owned()));
}

#[test]
fn mutating_which_case_hides_the_stroke_or_the_opacity_is_caught() {
    let rules = AnchorRules {
        fill_keeps_opacity: false,
        ..AnchorRules::BASELINE
    };
    let bad = mismatches(&rules);
    assert_eq!(bad.len(), 459);
    assert!(bad.contains(&"1".to_owned()));
}

#[test]
fn a_corrupted_oracle_row_is_detected() {
    let mut all = rows();
    // Flip the remembered stroke of one expectation.
    all[1].applied.pre_opacity = Remembered::Set(0.123);
    let row = &all[1];
    let applied = camouflage(row.has_fill, &row.authored);
    assert!(!same(&applied, &row.applied));
}
